{
  "qid": "0026_L3_01",
  "sample_id": "0026",
  "gen_prompt": "设定：一场分类事故已经被彻底纠正。画出宁波轨道交通从纠错光门中驶出的瞬间，使其成为画面主体。采用前侧方约四十五度视角，主体完整入画并位于中央；场景设在夜间的奇幻展厅。",
  "invocation": "L3",
  "knowledge_dim": "城市轨道交通系统身份识别、交通制式分类与排他性辨析",
  "fidelity_checks": [
    {
      "check": "主体应具有至少一种足以识别其城市地铁系统属性的视觉要素。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "1"
        ],
        "derivation_chain": "题面前提为分类事故已纠正且主体是宁波轨道交通 → 约束[1]要求该概念至少呈现一种可识别的城市地铁系统要素 → 画面主体必须能够从车辆、线路设施、车站设施、导向系统或系统标识等视觉证据中被识别为城市地铁系统"
      },
      "rubric": {
        "tier_0": "0 Fail：主体缺失，或只呈现抽象光影、普通建筑、一般车辆等，完全没有可识别的城市地铁系统视觉证据。",
        "tier_1": "1 Pass：至少一种城市地铁系统要素清晰可辨，例如典型地铁列车、专用线路或车站设施；不依赖画外说明即可完成基本分类。",
        "tier_2": "2 Excel：在达到 Pass 的基础上，同时以车辆结构和配套设施等多类相互印证的细节建立明确类别，且关键结构精细、分类毫不含混。"
      },
      "variants_used": "未锁定具体变体；接受清单所列任一种或其他合法的城市地铁系统视觉要素。",
      "visibility_requirement": "主体完整入画时，至少一种类别证据须达到可辨尺度；若所有证据均因过小、强光遮蔽或造型含混而不可判读，本条记 Fail。"
    },
    {
      "check": "画面应提供至少一种可将主体明确归属于宁波轨道交通的地域或系统身份线索。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "2"
        ],
        "derivation_chain": "题面指定主体为宁波轨道交通 → 约束[2]要求其具备区别于其他城市系统的宁波身份信息 → 画面中必须出现可读系统文字、可识别标志、宁波站名线路信息或宁波地域环境与主体的明确组合等身份线索"
      },
      "rubric": {
        "tier_0": "0 Fail：没有任何可识别的宁波身份线索，或线索模糊到只能判断为某个未指明城市的系统。",
        "tier_1": "1 Pass：至少一种合法身份线索清楚可辨，足以将主体明确归属于宁波轨道交通。",
        "tier_2": "2 Excel：在达到 Pass 的基础上，至少两种彼此一致的身份线索相互印证，例如系统标识与可读名称、站名线路信息与宁波地域环境同时准确呈现。"
      },
      "variants_used": "未锁定具体变体；接受清单列出的任一合法宁波身份信息或其他等效、可验证的合法线索。",
      "visibility_requirement": "身份线索可位于主体或展厅环境，但必须清晰可见；文字若作为唯一证据，须达到可读程度，标志或地域组合若作为唯一证据，须达到可识别程度，否则记 Fail。"
    },
    {
      "check": "完成纠错后的主体不得被塑造成依靠普通道路行驶的无轨道路车辆。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "3"
        ],
        "derivation_chain": "约束[3]排除普通道路上的无轨道路交通工具 → 题面设定分类事故已经纠正 → 纠正后的宁波轨道交通主体不得呈现公共汽车、小汽车、出租车、自行车或类似道路车辆的决定性形态"
      },
      "rubric": {
        "tier_0": "0 Fail：主体明确具有普通道路车辆的决定性结构或运行关系，例如汽车式车轮、道路车道运行或公共汽车式整体造型。",
        "tier_1": "1 Pass：主体未呈现普通道路无轨车辆的决定性特征，类别与道路车辆不存在明确冲突。",
        "tier_2": "2 Excel：在达到 Pass 的基础上，通过清楚的城市地铁车辆结构及专用运行关系，精确消除了与公共汽车、汽车等道路车辆混淆的可能。"
      },
      "variants_used": "未选取合法变体；检查覆盖清单所列全部禁用道路车辆形态。",
      "visibility_requirement": "完整主体及其下部运行关系应可见；若明确出现禁用结构即记 Fail。若没有禁用证据但细节较弱，可记 Pass，类别识别不足另由检查1判定。"
    },
    {
      "check": "完成纠错后的主体不得呈现为航空器或船舶。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "4"
        ],
        "derivation_chain": "约束[4]排除航空与水上交通工具 → 题面设定错误分类已纠正 → 主体不得以机翼、旋翼、船体、水面航行等决定性视觉语法出现"
      },
      "rubric": {
        "tier_0": "0 Fail：主体明确被画成飞机、直升机、飞船式航空器、船舶，或正在以航空或水上航行方式运行。",
        "tier_1": "1 Pass：主体不存在航空器或船舶的决定性结构与运行方式。",
        "tier_2": "2 Excel：在达到 Pass 的基础上，即使处于奇幻光门场景，仍以精确的地面城市地铁结构和运行关系保持类别清晰，毫无飞行器或船舶化歧义。"
      },
      "variants_used": "未选取合法变体；检查覆盖航空器与船舶两类禁用形态。",
      "visibility_requirement": "主体整体轮廓和运行界面须可判读；明确出现机翼、旋翼、船体或水面航行关系即记 Fail，装饰性光翼若不改变主体类别不单独判错。"
    },
    {
      "check": "主体不得采用高速铁路动车组或其他高速干线列车的决定性外形与场景语法。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "5"
        ],
        "derivation_chain": "约束[5]排除国家干线铁路与高速铁路系统 → 高速动车组是其中一类被排除对象 → 分类纠正后的主体不得呈现长鼻流线车头、高速铁路站场或完整高速列车识别语法"
      },
      "rubric": {
        "tier_0": "0 Fail：主体明显采用长鼻式高速动车组外形，或被置于具有决定性高速铁路特征的站场中并作为该系统列车呈现。",
        "tier_1": "1 Pass：主体没有高速动车组的决定性外形或高速铁路运行场景证据。",
        "tier_2": "2 Excel：在达到 Pass 的基础上，车头比例、车门窗布局与城市通勤车辆语法处理精确，可清楚排除高速动车组类别。"
      },
      "variants_used": "未选取合法变体；本条专门覆盖约束[5]中的高速铁路动车组与高速铁路场景形态。",
      "visibility_requirement": "题面规定的前侧方视角应使车头和侧面轮廓可见；若这些区域被光门完全遮住而无法分类，本条最高记 Pass，明确画成高速动车组则记 Fail。"
    },
    {
      "check": "主体不得采用普通国家铁路客车、干线机车车辆或国家铁路火车站的决定性识别语法。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "5"
        ],
        "derivation_chain": "约束[5]同时排除普通铁路客运与干线铁路系统 → 题面中的分类纠正要求排除这类近邻类别 → 主体及其配套环境不得被塑造成机车牵引客车、普通铁路车厢或国家铁路车站"
      },
      "rubric": {
        "tier_0": "0 Fail：主体明显是干线机车、普通铁路客车编组，或展厅外部运行环境明确模拟国家铁路火车站并把主体归入该系统。",
        "tier_1": "1 Pass：没有普通国家铁路客运系统的决定性车辆或场站特征。",
        "tier_2": "2 Excel：在达到 Pass 的基础上，通过高密度车门、城市通勤车厢比例或相匹配的专用设施等精细证据，明确排除普通铁路客运类别。"
      },
      "variants_used": "未选取合法变体；本条覆盖约束[5]中的干线铁路机车车辆、普速铁路客车和国家铁路火车站。",
      "visibility_requirement": "主体侧面与邻近环境达到可判尺度即可；若未出现任何禁用证据则可记 Pass，若明确采用机车牵引或普通铁路客车语法则记 Fail。"
    },
    {
      "check": "主体不得呈现蒸汽机车、柴油机车牵引列车或货运列车形态。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "6"
        ],
        "derivation_chain": "约束[6]排除蒸汽牵引、内燃牵引与货运列车 → 题面设定分类纠正完成 → 主体不得保留烟囱锅炉、独立柴油机车牵引、货车车厢等错误类别结构"
      },
      "rubric": {
        "tier_0": "0 Fail：主体明确出现蒸汽机车锅炉烟囱、独立柴油机车牵引结构、敞车罐车集装箱货车等任一种决定性形态。",
        "tier_1": "1 Pass：未出现上述牵引方式或货运编组的决定性视觉特征。",
        "tier_2": "2 Excel：在达到 Pass 的基础上，动力车辆一体化与城市客运车厢结构表现完整，乘客运输属性明确且无任何机车牵引或货运化歧义。"
      },
      "variants_used": "未选取合法变体；覆盖清单列出的三类禁用列车形态。",
      "visibility_requirement": "车头、车身及可见编组部分均纳入判断；任一可见部分明确出现禁用形态即记 Fail，背景装饰中的微小无关模型不视为主体违规。"
    },
    {
      "check": "主体及其运行结构不得采用单根承载梁、悬挂单轨或专用磁浮导轨等非地铁制式。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "7"
        ],
        "derivation_chain": "约束[7]排除跨座式单轨、悬挂式单轨和磁悬浮制式 → 题面前提要求恢复正确分类 → 从光门驶出的主体必须避免单梁跨坐、梁下悬挂或专用磁浮导轨关系"
      },
      "rubric": {
        "tier_0": "0 Fail：主体明确跨坐在单根梁上、悬挂于单根高架梁下，或以可识别的专用磁浮导轨结构运行。",
        "tier_1": "1 Pass：主体与可见运行结构未呈现上述非地铁制式的决定性关系。",
        "tier_2": "2 Excel：在达到 Pass 的基础上，主体下部运行界面和线路结构清楚完整，能以精确结构证据排除单轨及磁浮类别。"
      },
      "variants_used": "未选取合法变体；覆盖跨座式单轨、悬挂式单轨与磁悬浮列车。",
      "visibility_requirement": "主体下部与光门出口附近的运行界面应至少部分可见；若明确出现单梁跨坐、梁下悬挂或专用磁浮导轨即记 Fail。"
    },
    {
      "check": "主体不得被表现为在普通市政道路路面上与社会车辆或行人混行的有轨电车。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "8"
        ],
        "derivation_chain": "约束[8]排除普通道路上的混行有轨电车 → 题面中的分类纠正要求消除该近邻类别 → 主体不得位于汽车车道中混行，也不得呈现行人可直接横穿其运行面的路面电车关系"
      },
      "rubric": {
        "tier_0": "0 Fail：主体明确在普通道路车道中与汽车并行，或行人直接穿行其路面轨道，整体被塑造成街道路面电车。",
        "tier_1": "1 Pass：未出现与社会车辆或行人混行的普通道路运行关系。",
        "tier_2": "2 Excel：在达到 Pass 的基础上，以清楚的专用路权、隔离边界或独立运行空间精确消除与路面电车的混淆。"
      },
      "variants_used": "未选取合法变体；覆盖道路中央与汽车混行及行人可直接穿行两类禁用形态。",
      "visibility_requirement": "光门出口及主体周边地面关系须达到可判程度；若没有混行证据可记 Pass，明确出现普通道路混行关系则记 Fail。"
    },
    {
      "check": "用于标识主体的名称、官方标志和完整专属涂装不得属于其他城市的轨道交通系统。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "9"
        ],
        "derivation_chain": "约束[9]禁止用其他城市系统身份标识宁波轨道交通 → 题面设定身份分类已纠正 → 主体上及与主体直接对应的标牌、线路信息和涂装不得出现其他城市的明确专属身份"
      },
      "rubric": {
        "tier_0": "0 Fail：主体或其直接配套标识明确使用其他城市的系统名称、官方标志或完整专属涂装，并将其作为主体身份。",
        "tier_1": "1 Pass：未发现与主体身份冲突的其他城市专属名称、官方标志或完整涂装。",
        "tier_2": "2 Excel：在达到 Pass 的基础上，所有可见名称、标志、线路信息与涂装均内部一致地指向宁波，没有混标、错标或疑似拼接。"
      },
      "variants_used": "未选取合法变体；覆盖其他城市地铁名称、官方标志和完整专属涂装。",
      "visibility_requirement": "只检查可见且与主体直接相关的身份信息；无法辨认的装饰字符不据此判为其他城市，但清楚可读的冲突标识出现一处即记 Fail。"
    }
  ],
  "alignment_checks": [
    {
      "check": "宁波轨道交通应作为画面主体并占据视觉主导地位。",
      "facet": "subject_prominence",
      "rubric": {
        "tier_0": "0 Fail：主体缺失，或被光门、展厅装饰等元素严重边缘化，无法成为视觉焦点。",
        "tier_1": "1 Pass：主体明确在场并占据画面主导，展厅与光门均为辅助元素。",
        "tier_2": "2 Excel：在达到 Pass 的基础上，主体体量、位置和视觉引导高度统一，第一视觉焦点明确且层次组织出色。"
      }
    },
    {
      "check": "主体应呈现从纠错光门中驶出的动态瞬间。",
      "facet": "fullbody_action",
      "rubric": {
        "tier_0": "0 Fail：主体静止陈列、驶向光门、远离光门但没有穿出关系，或完全未出现光门。",
        "tier_1": "1 Pass：主体的朝向、位置和运动状态清楚表现其正在从光门中驶出。",
        "tier_2": "2 Excel：在达到 Pass 的基础上，穿越边界、前后运动层次及动态姿态表达鲜明，瞬间感强且无需猜测。"
      }
    },
    {
      "check": "采用前侧方约四十五度视角，主体完整入画并位于画面中央。",
      "facet": "spatial_2d",
      "rubric": {
        "tier_0": "0 Fail：主体明显偏至边缘、被大幅裁切，或采用纯正侧面、纯正面、背面等明显不符的视角。",
        "tier_1": "1 Pass：主体基本完整、居中，且前部与一侧车身同时可见，符合约四十五度的前侧方观察关系。",
        "tier_2": "2 Excel：在达到 Pass 的基础上，完整轮廓、居中位置和前侧方透视均控制精准，空间层次清楚且主体结构展示充分。"
      }
    },
    {
      "check": "场景应为夜间奇幻展厅，并包含与分类纠正设定相符的纠错光门。",
      "facet": "virtual_scene",
      "rubric": {
        "tier_0": "0 Fail：场景不是展厅、明显为白昼，或缺少纠错光门，导致题面虚构设定未成立。",
        "tier_1": "1 Pass：夜间展厅与发光的纠错入口均清楚呈现，虚构场景内部基本自洽。",
        "tier_2": "2 Excel：在达到 Pass 的基础上，展陈空间、夜间环境和光门效果形成统一且可信的虚构世界，分类纠正主题通过环境叙事清晰可感。"
      }
    }
  ],
  "leak_check": {
    "对照表": [
      {
        "constraint_ref": "1",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "2",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "3",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "4",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "5",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "6",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "7",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "8",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "9",
        "题面中是否出现": "无"
      }
    ],
    "结论": "全为无"
  },
  "notes": "题面仅点名概念并给出分类纠正前提，未泄露正确制式、身份线索或排除类别。合法身份线索与城市地铁视觉要素均未锁定具体变体；前侧方完整视角保证车头、侧面及下部运行关系原则上可判。透视缩短、光门局部遮挡和环境光导致的合理变形不得误判，只有决定性禁用结构或身份冲突才触发相应 Fail。"
}
